#include <unistd.h>
#include <stdio.h>
int main() {
    char *message = "Hello, world!\n";
    ssize_t bytes_written = write(1, message, strlen(message));
    if (bytes_written == -1) {
        perror("write failed");
        return 1;
    }
    printf("Wrote %ld bytes\n", bytes_written);
    return 0;
}
